import pyAether as pyScript

def trace_cdfset(paramId, attrs):
    results = {}
    for attr, value in attrs.items():
        ok = pyScript.cdfSet(paramId=paramId,
                             attr=pyScript.emyString(attr),
                             value=pyScript.emyString(value))
        results[attr] = ok
    return results

import pyAether as pyScript

def vary_mdesession(designs):
    sessions = {}
    for lib, cell, view in designs:
        mde = pyScript.MdeSession.open(lib, cell, view)
        sessions[(lib, cell, view)] = mde
    return sessions

import pyAether as pyScript

def vary_mdesession_run(lib, cell, views):
    results = {}
    for view in views:
        mde = pyScript.MdeSession.open(lib, cell, view)
        if mde is None:
            results[view] = None
            continue
        results[view] = mde.run()
        mde.close()
    return results

import pyAether as pyScript

def vary_cdfcreatecdf(cells, lib, simInfoOrder=""):
    cdfs = {}
    for cell in cells:
        cid = pyScript.cdfCreateCDF(
            lib=pyScript.emyString(lib),
            cell=pyScript.emyString(cell),
            simInfoOrder=pyScript.emyString(simInfoOrder))
        cdfs[cell] = cid
    return cdfs

