def vary_cdfsetsiminfo(cdfId, sim_configs):
    results = {}
    for sim_type, np_val in sim_configs:
        ok = pyScript.cdfSetSimInfo(
            cdfDataId=cdfId,
            type=pyScript.emyString(sim_type),
            netlistProcedure=pyScript.emyString(np_val))
        results[sim_type] = ok
    return results
